CREATE TABLE point_account(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,balance BIGINT NOT NULL DEFAULT 0,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,delete_state INT NOT NULL DEFAULT 0,UNIQUE KEY uk_user(user_id));
CREATE TABLE point_record(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,source VARCHAR(20) NOT NULL,source_id VARCHAR(40) NOT NULL,amount INT NOT NULL,record_date DATE NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,delete_state INT NOT NULL DEFAULT 0,UNIQUE KEY uk_source_user(source,source_id,user_id),INDEX idx_user(user_id,id));
